import 'package:flutter/foundation.dart';\nimport 'package:dio/dio.dart';\nimport 'package:aldjawal_travel_app/models/budget_recommendation.dart';\n\n/// Service for budget-based travel recommendations\nclass BudgetRecommendationService {\n  final Dio _dio;\n  final String _baseUrl;\n\n  BudgetRecommendationService({\n    String baseUrl = 'https://your-api.example.com',\n    Dio? dio,\n  })\n      : _baseUrl = baseUrl,\n        _dio = dio ??\n            Dio(\n              BaseOptions(\n                baseUrl: baseUrl,\n                connectTimeout: const Duration(seconds: 10),\n                receiveTimeout: const Duration(seconds: 10),\n                contentType: Headers.jsonContentType,\n              ),\n            );\n\n  /// Get list of countries user can visit within their budget\n  Future<List<BudgetRecommendation>> getAffordableDestinations({\n    required String passportCode,\n    required double budgetUSD,\n    required int estimatedDays,\n  }) async {\n    try {\n      final response = await _dio.post(\n        '/api/v1/budget/recommendations',\n        data: {\n          'passportCode': passportCode,\n          'budgetUSD': budgetUSD,\n          'estimatedDays': estimatedDays,\n        },\n      );\n\n      final List<dynamic> data = response.data['recommendations'] as List<dynamic>? ?? [];\n      \n      final recommendations = data\n          .cast<Map<String, dynamic>>()\n          .map((json) => BudgetRecommendation.fromJson(json))\n          .toList();\n\n      return BudgetRecommendation.sortByAffordability(recommendations);\n    } on DioException catch (e) {\n      debugPrint('Budget recommendations error: ${e.message}');\n      return [];\n    }\n  }\n\n  /// Get detailed breakdown for a specific country\n  Future<Map<String, dynamic>?> getBudgetBreakdown({\n    required String passportCode,\n    required String destinationCode,\n    required int days,\n  }) async {\n    try {\n      final response = await _dio.get(\n        '/api/v1/budget/breakdown',\n        queryParameters: {\n          'passportCode': passportCode,\n          'destinationCode': destinationCode,\n          'days': days,\n        },\n      );\n\n      return response.data as Map<String, dynamic>?;\n    } on DioException catch (e) {\n      debugPrint('Budget breakdown error: ${e.message}');\n      return null;\n    }\n  }\n\n  /// Calculate savings if user uses alternative passport\n  Future<Map<String, dynamic>?> comparePassportSavings({\n    required String destinationCode,\n    required int days,\n  }) async {\n    try {\n      final response = await _dio.get(\n        '/api/v1/budget/passport-comparison',\n        queryParameters: {\n          'destinationCode': destinationCode,\n          'days': days,\n        },\n      );\n\n      return response.data as Map<String, dynamic>?;\n    } on DioException catch (e) {\n      debugPrint('Passport comparison error: ${e.message}');\n      return null;\n    }\n  }\n\n  void dispose() {\n    _dio.close();\n  }\n}\n